     1	package service;
     2	
     3	import domain.RefundLine;
     4	import infra.PgsimClient.RefundRow;
     5	import infra.RefundFileWriter;
     6	
     7	import java.util.ArrayList;
     8	import java.util.List;
     9	
    10	/** Attaches PG refund numbers from a batch status to the lines we sent in that batch. */
    11	public final class RefundResultMatcher {
    12	    private RefundResultMatcher() {}
    13	
    14	    /** Returns how many lines got a refund number. Each PG row is used at most once. */
    15	    public static int apply(List<RefundLine> sent, List<RefundRow> rows) {
    16	        List<RefundRow> free = new ArrayList<>(rows);
    17	        int matched = 0;
    18	        for (RefundLine line : sent) {
    19	            String ref = RefundFileWriter.merchantRef(line);
    20	            for (int i = 0; i < free.size(); i++) {
    21	                RefundRow row = free.get(i);
    22	                if (row.tid().equals(line.tid()) && row.amount() == line.amount() && row.aux().equals(ref)) {
    23	                    line.done(row.refundNo());
    24	                    free.remove(i);
    25	                    matched++;
    26	                    break;
    27	                }
    28	            }
    29	        }
    30	        return matched;
    31	    }
    32	}
=================== src/util/Refs.java
     1	package util;
     2	
     3	/** Reference strings sent to the PG: [A-Za-z0-9-] only, at most 24 characters. */
     4	public final class Refs {
     5	    public static final int MAX = 24;
     6	
     7	    private Refs() {}
     8	
     9	    public static String sanitize(String raw) {
    10	        StringBuilder sb = new StringBuilder();
    11	        for (char c : raw.toCharArray()) {
    12	            if ((c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '-') {
    13	                sb.append(c);
    14	            } else if (c == '_' || c == ' ' || c == '/') {
    15	                sb.append('-');
    16	            }
    17	        }
    18	        String s = sb.toString();
    19	        return s.length() > MAX ? s.substring(s.length() - MAX) : s;
    20	    }
    21	}
