     5	/** Refund of one order line. Mutable status, owned by the refund repository. */
     6	public final class RefundLine {
     7	    public enum Status {
     8	        /** accepted by CS, waiting for the nightly refund run */
     9	        REQUESTED,
    10	        /** sent to the PG in a refund batch, no PG refund number yet */
    11	        SUBMITTED,
    12	        /** PG refund number received */
