    20	    private final long amount;
    21	    private final LocalDate requestedOn;
    22	    private Status status = Status.REQUESTED;
    23	    private String batchId;
    24	    private String refundNo;
    25	
    26	    public RefundLine(String requestId, String orderNo, int lineNo, String tid, long amount, LocalDate requestedOn) {
    27	        this.requestId = requestId;
    28	        this.orderNo = orderNo;
    29	        this.lineNo = lineNo;
    30	        this.tid = tid;
    31	        this.amount = amount;
    32	        this.requestedOn = requestedOn;
    33	    }
    34	
    35	    public String requestId() { return requestId; }
    36	    public String orderNo() { return orderNo; }
    37	    public int lineNo() { return lineNo; }
    38	    public String tid() { return tid; }
    39	    public long amount() { return amount; }
    40	    public LocalDate requestedOn() { return requestedOn; }
    41	    public Status status() { return status; }
    42	    public String batchId() { return batchId; }
    43	    public String refundNo() { return refundNo; }
    44	
    45	    public void submitted(String batchId) {
    46	        this.status = Status.SUBMITTED;
    47	        this.batchId = batchId;
    48	    }
    49	
    50	    public void done(String refundNo) {
    51	        this.status = Status.DONE;
    52	        this.refundNo = refundNo;
    53	    }
    54	
    55	    @Override
    56	    public String toString() {
    57	        return requestId + "/" + orderNo + "#" + lineNo + " " + amount + " " + status;
    58	    }
    59	}
