    20	        Order earbuds = api.placeOrder("C-4127", List.of("SKU-EARB"), 0, ORDER_DAY);
    21	        Order films = api.placeOrder("C-1188", List.of("SKU-FILM", "SKU-FILM", "SKU-STND"), 1000, ORDER_DAY);
    22	
    23	        api.requestRefund(chargers.orderNo(), List.of(1, 2), REFUND_DAY);
    24	        api.requestRefund(caseOrder.orderNo(), List.of(2), REFUND_DAY);
    25	        api.requestRefund(earbuds.orderNo(), List.of(1), REFUND_DAY);
    26	        api.requestRefund(films.orderNo(), List.of(1), REFUND_DAY);
    27	        RunResult run = api.runRefunds(REFUND_DAY);
    28	
    29	        t.test("nightly refund run submits every requested item", () -> {
    30	            TestSupport.eq(5, run.submitted(), "items submitted");
    31	            TestSupport.eq(1, run.batchIds().size(), "PG batches");
    32	        });
    33	
    34	        t.test("customer C-2051 gets both returned power banks back (31,800원)", () -> {
    35	            CustomerStatement s = api.statement(chargers.orderNo());
    36	            TestSupport.eq(38_700L, s.paid(), "paid");
    37	            TestSupport.eq(31_800L, s.refunded(), "refunded to the customer by the PG");
    38	            TestSupport.eq(6_900L, s.balance(), "remaining payment");
    39	        });
    40	
    41	        t.test("every returned item shows 환불 완료 with a PG refund number", () -> {
    42	            for (Order o : List.of(chargers, caseOrder, earbuds, films)) {
    43	                for (CustomerStatement.Line l : api.statement(o.orderNo()).lines()) {
    44	                    if (l.state().equals("구매")) continue;
    45	                    TestSupport.eq("환불 완료", l.state(), o.orderNo() + " line " + l.lineNo());
    46	                    TestSupport.check(l.refundNo() != null, o.orderNo() + " line " + l.lineNo() + " has no refund number");
    47	                }
    48	            }
    49	        });
    50	
    51	        t.test("nothing is left waiting at the PG after the nightly run", () ->
    52	                TestSupport.eq(List.of(), api.awaitingPg().stream().map(Object::toString).toList(), "awaiting"));
    53	
    54	        t.test("other customers' partial refunds are paid", () -> {
    55	            TestSupport.eq(9_900L, api.statement(caseOrder.orderNo()).refunded(), "C-3310 case");
    56	            TestSupport.eq(49_000L, api.statement(earbuds.orderNo()).refunded(), "C-4127 earbuds");
    57	            TestSupport.eq(7_615L, api.statement(films.orderNo()).refunded(), "C-1188 one film after coupon");
    58	            TestSupport.eq(0L, api.statement(earbuds.orderNo()).balance(), "C-4127 balance");
    59	        });
    60	
    61	        t.test("statement text for C-3310", () -> {
    62	            String text = api.statementText(caseOrder.orderNo());
    63	            TestSupport.check(text.contains("투명 젤리 케이스  9,900원  환불 완료 [RF"), text);
    64	            TestSupport.check(text.contains("결제 22,800원 / 환불 9,900원 / 잔액 12,900원"), text);
    65	        });
    66	
    67	        t.test("an item cannot be refunded twice", () -> {
    68	            try {
    69	                api.requestRefund(caseOrder.orderNo(), List.of(2), REFUND_DAY.plusDays(1));
    70	                throw new AssertionError("second refund of the same item was accepted");
    71	            } catch (IllegalStateException expected) {
    72	                // ok
    73	            }
    74	        });
    75	
    76	        t.test("a run with nothing pending sends nothing", () -> {
    77	            RunResult again = api.runRefunds(REFUND_DAY.plusDays(1));
    78	            TestSupport.eq(0, again.submitted(), "submitted");
    79	            TestSupport.eq(List.of(), again.batchIds(), "batches");
    80	        });
    81	
    82	        t.finish();
    83	    }
    84	}
