    28	    /** One line per unit: ordering the same SKU twice gives two lines. */
    29	    public Order place(String customerId, List<String> skus, long coupon, LocalDate day) {
    30	        if (skus.isEmpty()) throw new IllegalArgumentException("empty cart");
    31	        List<CatalogItem> items = new ArrayList<>();
    32	        for (String sku : skus) {
    33	            CatalogItem item = catalog.get(sku);
