    38	        List<OrderLine> lines = new ArrayList<>();
    39	        for (int i = 0; i < items.size(); i++) {
    40	            CatalogItem it = items.get(i);
    41	            lines.add(new OrderLine(i + 1, it.sku(), it.name(), it.price(), discounts.get(i)));
    42	        }
    43	        String orderNo = orders.nextOrderNo(day.format(DateTimeFormatter.BASIC_ISO_DATE));
    44	        long total = lines.stream().mapToLong(OrderLine::paid).sum();
    45	        String tid = pg.pay(mid, total, orderNo);
    46	        Order order = new Order(orderNo, customerId, tid, List.copyOf(lines), coupon);
    47	        orders.save(order);
    48	        return order;
    49	    }
