     9	
    10	/** Tiny assertion runner (no external test framework on the batch host). */
    11	final class TestSupport {
    12	    private final String suite;
    13	    private final List<String> failures = new ArrayList<>();
    14	    private int passed;
    15	
    16	    TestSupport(String suite) {
    17	        this.suite = suite;
    18	    }
    19	
    20	    interface Body { void run() throws Exception; }
    21	
    22	    void test(String name, Body body) {
    23	        try {
    24	            body.run();
    25	            passed++;
    26	            System.out.println("ok   - " + name);
    27	        } catch (AssertionError | Exception e) {
    28	            failures.add(name + ": " + e.getMessage());
    29	            System.out.println("FAIL - " + name + ": " + e.getMessage());
    30	        }
    31	    }
    32	
    33	    static void eq(Object expected, Object actual, String msg) {
    34	        if (!Objects.equals(expected, actual)) {
    35	            throw new AssertionError(msg + " (expected " + expected + ", got " + actual + ")");
    36	        }
    37	    }
    38	
    39	    static void check(boolean cond, String msg) {
    40	        if (!cond) throw new AssertionError(msg);
    41	    }
    42	
    43	    /** Fresh PG sandbox and work dir per test. */
    44	    static AppConfig sandbox() throws IOException {
    45	        Path tmp = Files.createTempDirectory("refund-desk-");
    46	        tmp.toFile().deleteOnExit();
    47	        return AppConfig.load().with("pg.home", tmp.resolve("pg").toString())
    48	                .with("refund.workDir", tmp.resolve("work").toString());
    49	    }
    50	
    51	    void finish() {
    52	        System.out.printf("%s: %d passed, %d failed%n", suite, passed, failures.size());
    53	        if (!failures.isEmpty()) System.exit(1);
    54	    }
    55	}
